static int
mlxsw_sp_port_add_cls_matchall_mirror(struct mlxsw_sp_port *mlxsw_sp_port,
				      struct tc_cls_matchall_offload *cls,
				      const struct tc_action *a,
				      bool ingress)
{
	struct mlxsw_sp_port_mall_tc_entry *mall_tc_entry;
	struct net *net = dev_net(mlxsw_sp_port->dev);
	enum mlxsw_sp_span_type span_type;
	struct mlxsw_sp_port *to_port;
	struct net_device *to_dev;
	int ifindex;
	int err;

	ifindex = tcf_mirred_ifindex(a);
	to_dev = __dev_get_by_index(net, ifindex);
	if (!to_dev) {
		netdev_err(mlxsw_sp_port->dev, "Could not find requested device\n");
		return -EINVAL;
	}

	if (!mlxsw_sp_port_dev_check(to_dev)) {
		netdev_err(mlxsw_sp_port->dev, "Cannot mirror to a non-spectrum port");
		return -ENOTSUPP;
	}
	to_port = netdev_priv(to_dev);

	mall_tc_entry = kzalloc(sizeof(*mall_tc_entry), GFP_KERNEL);
	if (!mall_tc_entry)
		return -ENOMEM;

	mall_tc_entry->cookie = cls->cookie;
	mall_tc_entry->type = MLXSW_SP_PORT_MALL_MIRROR;
	mall_tc_entry->mirror.to_local_port = to_port->local_port;
	mall_tc_entry->mirror.ingress = ingress;
	list_add_tail(&mall_tc_entry->list, &mlxsw_sp_port->mall_tc_list);

	span_type = ingress ? MLXSW_SP_SPAN_INGRESS : MLXSW_SP_SPAN_EGRESS;
	err = mlxsw_sp_span_mirror_add(mlxsw_sp_port, to_port, span_type);
	if (err)
		goto err_mirror_add;
	return 0;

err_mirror_add:
	list_del(&mall_tc_entry->list);
	kfree(mall_tc_entry);
	return err;
}

static int mlxsw_sp_port_add_cls_matchall(struct mlxsw_sp_port *mlxsw_sp_port,
					  __be16 protocol,
					  struct tc_cls_matchall_offload *cls,
					  bool ingress)
{
	const struct tc_action *a;
	int err;

	if (!tc_single_action(cls->exts)) {
		netdev_err(mlxsw_sp_port->dev, "only singular actions are supported\n");
		return -ENOTSUPP;
	}

	tc_for_each_action(a, cls->exts) {
		if (!is_tcf_mirred_mirror(a) || protocol != htons(ETH_P_ALL))
			return -ENOTSUPP;

		err = mlxsw_sp_port_add_cls_matchall_mirror(mlxsw_sp_port, cls,
							    a, ingress);
		if (err)
			return err;
	}

	return 0;
}

static void mlxsw_sp_port_del_cls_matchall(struct mlxsw_sp_port *mlxsw_sp_port,
					   struct tc_cls_matchall_offload *cls)
{
	struct mlxsw_sp *mlxsw_sp = mlxsw_sp_port->mlxsw_sp;
	struct mlxsw_sp_port_mall_tc_entry *mall_tc_entry;
	enum mlxsw_sp_span_type span_type;
	struct mlxsw_sp_port *to_port;

	mall_tc_entry = mlxsw_sp_port_mirror_entry_find(mlxsw_sp_port,
							cls->cookie);
	if (!mall_tc_entry) {
		netdev_dbg(mlxsw_sp_port->dev, "tc entry not found on port\n");
		return;
	}

	switch (mall_tc_entry->type) {
	case MLXSW_SP_PORT_MALL_MIRROR:
		to_port = mlxsw_sp->ports[mall_tc_entry->mirror.to_local_port];
		span_type = mall_tc_entry->mirror.ingress ?
				MLXSW_SP_SPAN_INGRESS : MLXSW_SP_SPAN_EGRESS;

		mlxsw_sp_span_mirror_remove(mlxsw_sp_port, to_port, span_type);
		break;
	default:
		WARN_ON(1);
	}

	list_del(&mall_tc_entry->list);
	kfree(mall_tc_entry);
}

static int mlxsw_sp_setup_tc(struct net_device *dev, u32 handle,
			     __be16 proto, struct tc_to_netdev *tc)
{
	struct mlxsw_sp_port *mlxsw_sp_port = netdev_priv(dev);
	bool ingress = TC_H_MAJ(handle) == TC_H_MAJ(TC_H_INGRESS);

	if (tc->type == TC_SETUP_MATCHALL) {
		switch (tc->cls_mall->command) {
		case TC_CLSMATCHALL_REPLACE:
			return mlxsw_sp_port_add_cls_matchall(mlxsw_sp_port,
							      proto,
							      tc->cls_mall,
							      ingress);
		case TC_CLSMATCHALL_DESTROY:
			mlxsw_sp_port_del_cls_matchall(mlxsw_sp_port,
						       tc->cls_mall);
			return 0;
		default:
			return -EINVAL;
		}
	}

	return -ENOTSUPP;
}

